"""Heat diffusion on a grid, with the stencil computed on the GPU via wgpu."""

import sys

import numpy as np
import wgpu

WORKGROUP = 8

SHADER = f"""
struct Dims {{
    width: u32,
    height: u32,
}};

@group(0) @binding(0) var<uniform> dims: Dims;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size({WORKGROUP}, {WORKGROUP}, 1)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {{
    let x = gid.x;
    let y = gid.y;
    let w = dims.width;
    let h = dims.height;
    if (x >= w || y >= h) {{
        return;
    }}
    let xl = select(x - 1u, x, x == 0u);
    let xr = select(x + 1u, x, x + 1u >= w);
    let yu = select(y - 1u, y, y == 0u);
    let yd = select(y + 1u, y, y + 1u >= h);
    let row = y * w;
    let self_v = src[row + x];
    let total = 4u * self_v
        + src[row + xl]
        + src[row + xr]
        + src[yu * w + x]
        + src[yd * w + x];
    dst[row + x] = total / 8u;
}}
"""


def parse(text):
    tokens = text.split()
    if len(tokens) < 3:
        raise ValueError("header must contain width, height and steps")
    width, height, steps = (int(t) for t in tokens[:3])
    if not (1 <= width <= 512 and 1 <= height <= 512):
        raise ValueError("width and height must be between 1 and 512")
    if not (0 <= steps <= 1000):
        raise ValueError("steps must be between 0 and 1000")
    cells = tokens[3:]
    if len(cells) != width * height:
        raise ValueError(f"expected {width * height} cells, got {len(cells)}")
    grid = np.array([int(c) for c in cells], dtype=np.int64)
    if grid.size and (grid.min() < 0 or grid.max() > 1_000_000):
        raise ValueError("cells must be between 0 and 1000000")
    return width, height, steps, grid.astype(np.uint32)


def diffuse(width, height, steps, grid):
    """Run `steps` stencil steps on the GPU and return the resulting grid."""
    if steps == 0:
        return grid.copy()

    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    nbytes = grid.nbytes
    usage = (
        wgpu.BufferUsage.STORAGE
        | wgpu.BufferUsage.COPY_SRC
        | wgpu.BufferUsage.COPY_DST
    )
    buf_a = device.create_buffer_with_data(data=grid.tobytes(), usage=usage)
    buf_b = device.create_buffer(size=nbytes, usage=usage)
    dims = device.create_buffer_with_data(
        data=np.array([width, height, 0, 0], dtype=np.uint32).tobytes(),
        usage=wgpu.BufferUsage.UNIFORM,
    )

    layout = device.create_bind_group_layout(
        entries=[
            {
                "binding": 0,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": wgpu.BufferBindingType.uniform},
            },
            {
                "binding": 1,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": wgpu.BufferBindingType.read_only_storage},
            },
            {
                "binding": 2,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": wgpu.BufferBindingType.storage},
            },
        ]
    )

    def bind_group(src, dst):
        return device.create_bind_group(
            layout=layout,
            entries=[
                {"binding": 0, "resource": {"buffer": dims, "offset": 0, "size": dims.size}},
                {"binding": 1, "resource": {"buffer": src, "offset": 0, "size": nbytes}},
                {"binding": 2, "resource": {"buffer": dst, "offset": 0, "size": nbytes}},
            ],
        )

    groups = [bind_group(buf_a, buf_b), bind_group(buf_b, buf_a)]
    pipeline = device.create_compute_pipeline(
        layout=device.create_pipeline_layout(bind_group_layouts=[layout]),
        compute={"module": device.create_shader_module(code=SHADER), "entry_point": "main"},
    )

    gx = (width + WORKGROUP - 1) // WORKGROUP
    gy = (height + WORKGROUP - 1) // WORKGROUP
    encoder = device.create_command_encoder()
    for step in range(steps):
        # Separate passes guarantee each step sees the previous step's writes.
        cpass = encoder.begin_compute_pass()
        cpass.set_pipeline(pipeline)
        cpass.set_bind_group(0, groups[step % 2])
        cpass.dispatch_workgroups(gx, gy, 1)
        cpass.end()
    device.queue.submit([encoder.finish()])

    result = buf_b if steps % 2 == 1 else buf_a
    data = device.queue.read_buffer(result)
    return np.frombuffer(data, dtype=np.uint32).copy()


def render(width, height, grid):
    rows = grid.reshape(height, width)
    lines = [" ".join(str(v) for v in row.tolist()) for row in rows]
    lines.append(f"SUM {int(grid.astype(np.int64).sum())}")
    return "\n".join(lines) + "\n"


def main(argv):
    if len(argv) < 2:
        print("usage: main.py <input-file>", file=sys.stderr)
        return 2
    with open(argv[1]) as f:
        width, height, steps, grid = parse(f.read())
    result = diffuse(width, height, steps, grid)
    sys.stdout.write(render(width, height, result))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

